What happens when this program starts?

var registry = map[string]func() string{}
func mustGet(n string) func() string {
	f, ok := registry[n]
	if !ok { panic("unknown provider " + n) }
	return f
}
var defaultProvider = mustGet("acme")
func init() { registry["acme"] = func() string { return "acme" } }
func main() { fmt.Println(defaultProvider()) }
